const express = require('express');
const app = express();

// Middleware to parse JSON bodies
app.use(express.json());

/**
 * Evaluate a caller-supplied rule expression against the request context.
 * @param {Object} req - Express request object
 * @returns {boolean} - Result of the evaluated rule expression
 */
function evalRule(req) {
  const expr = req.body.rule; // e.g., 'ctx.amount > 100'
  const ctx = { ctx: req.body.context, req };
  return Function('ctx', 'req', `return (${expr});`)(ctx.ctx, req);
}

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

/**
 * POST /check - Evaluate a rule expression against the request context
 * Body expects:
 *   - rule: string - the rule expression to evaluate (e.g., 'ctx.amount > 100')
 *   - context: object - the context data to evaluate against (optional)
 *
 * Example request:
 * {
 *   "rule": "ctx.amount > 100",
 *   "context": { "amount": 150 }
 * }
 *
 * Example response:
 * { "result": true }
 */
app.post('/check', (req, res) => {
  try {
    if (!req.body.rule) {
      return res.status(400).json({ error: 'Missing required field: rule' });
    }

    const result = evalRule(req);
    res.json({ result });
  } catch (error) {
    res.status(400).json({ error: error.message });
  }
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

