// Simple parser for SaaS functions
function ssfParse(fn) {
  // Parse SaaS function call, e.g., "user(name='Alice')"
  const regex = /([a-zA-Z_][a-zA-Z0-9_]*)\s*\(([\s\S]*)\)/;
  const match = fn.match(regex);
  if (match) {
    const funcName = match[1];
    const args = {};
    if (match[2]) {
      const argRegex = /(\w+)\s*=\s*(['"])(.*?)\2/g;
      let argMatch;
      while ((argMatch = argRegex.exec(match[2])) !== null) {
        args[argMatch[1]] = argMatch[3];
      }
    }
    return { funcName, args };
  }
  return null;
}

// Evaluate a caller-supplied rule expression against the request
function evalRule(req) {
  const expr = req.body.rule;
  const ctx = { ctx: req.body.context, req };
  return Function('ctx', 'req', `return (${expr});`)(ctx.ctx, req);
}

// SaaS function implementations
const ssf = {
  user: (args, ctx) => {
    const name = args.name;
    const users = ctx.ctx.users || [];
    return users.find(u => u.name === name);
  },
  product: (args, ctx) => {
    const productId = args.productId;
    const products = ctx.ctx.products || [];
    return products.find(p => p.id === productId);
  },
};

// SaaS function evaluator
function ssfEval(fn, ctx) {
  const parsed = ssfParse(fn);
  if (!parsed) return undefined;
  const fnImpl = ssf[parsed.funcName];
  if (!fnImpl) return undefined;
  return fnImpl(parsed.args, ctx);
}

